sig LoginState {}
one sig Unlocked extends LoginState {}
one sig Locked extends LoginState {}

var var state: LoginState
var var failureCount: Int

pred loginFailed {
  failureCount' = failureCount + 1
  failureCount >= 5 => state' = Locked
}

pred loginSuccess {
  failureCount' = 0
  state' = Unlocked
}

fact Invariants {
  always (state = Locked => failureCount >= 5)
}

sig OrderState {}
one sig Pending extends OrderState {}
one sig Paid extends OrderState {}
one sig Backorder extends OrderState {}

var var state: OrderState
var var stock: Int

pred paymentSuccess {
  stock > 0 => {
    stock' = stock - 1
    state' = Paid
  }
  stock = 0 => state' = Backorder
}

fact Invariants {
  always (state = Paid => stock >= 0)
  always (state = Backorder => stock = 0)
}

sig FileType {}
one sig PDF extends FileType {}
one sig DOCX extends FileType {}

pred validateUpload[fileSize: Int, fileType: FileType] {
  fileSize <= 100 * 1024 * 1024
  fileType in PDF + DOCX
}
